import pathlib
p='navigation.py'; s=pathlib.Path(p).read_text()
old='''async def show_text(message: Message, text: str, **kwargs):
    # Telegram cannot edit a photo into text. Keep the useful QR and send a menu.
    if message.text is None:
        return await message.answer(text, **kwargs)'''
new='''async def show_text(message: Message, text: str, **kwargs):
    # A photo card stays a single screen: short texts become its caption, long ones replace it.
    if message.text is None:
        if message.photo and len(text) <= 1024 and not getattr(message, "_is_qr", False):
            try:
                return await message.edit_caption(caption=text, **kwargs)
            except TelegramBadRequest as error:
                if "message is not modified" in error.message.lower():
                    return None
        sent = await message.answer(text, **kwargs)
        if message.photo and message.from_user and message.from_user.is_bot:
            try:
                await message.delete()
            except TelegramBadRequest:
                pass
        return sent'''
assert old in s; s=s.replace(old,new,1)
pathlib.Path(p).write_text(s); print('navigation patched')
