Every onboarding step has its own card with a 4-step progress tracker, so the user
always sees where they are. Re-runnable on the Mac: python3 assets/make_cards.py
"""
import os
import subprocess
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "src")
CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
STEPS = ("Устройство", "Приложение", "Профиль", "Включение")

S = 'fill="none" stroke="#78AAFF" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"'
