               f'<path d="M94 178 H146"/></g></svg>',
    "power": f'<svg viewBox="0 0 240 240"><g {S}><rect x="30" y="80" width="180" height="88" rx="44" fill="#2F6BFF" stroke="#2F6BFF"/>'
             f'<circle cx="166" cy="124" r="32" fill="#FFFFFF" stroke="#FFFFFF"/></g>'
             f'<path d="M120 22 V50 M70 38 L82 58 M170 38 L158 58" {S}/></svg>',
    "done": '<svg viewBox="0 0 240 240"><circle cx="120" cy="120" r="96" fill="#1E9E5A"/>'
            '<path d="M76 122 L106 152 L166 92" fill="none" stroke="#fff" stroke-width="18" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    "help": f'<svg viewBox="0 0 240 240"><g {S}><circle cx="120" cy="120" r="88"/><circle cx="120" cy="120" r="40"/>'
            f'<path d="M58 58 L92 92 M182 58 L148 92 M58 182 L92 148 M182 182 L148 148"/></g></svg>',
    "list": f'<svg viewBox="0 0 240 240"><g {S}><rect x="40" y="40" width="160" height="160" rx="22"/>'
            f'<path d="M78 92 H162 M78 124 H162 M78 156 H130"/></g></svg>',
    "doc": f'<svg viewBox="0 0 240 240"><g {S}><path d="M64 28 H146 L184 66 V212 H64 Z"/><path d="M146 28 V66 H184"/>'
           f'<path d="M92 112 H156 M92 142 H156 M92 172 H132"/></g></svg>',
    "key": f'<svg viewBox="0 0 240 240"><g {S}><circle cx="86" cy="120" r="40"/><path d="M126 120 H208 M178 120 V150 M204 120 V144"/></g></svg>',
}

# name, kicker, headline, subline, icon, step (1..4 / 5 = all done / None)
CARDS = [
    ("step1", "Шаг 1 из 4", "Выберите устройство", "Для каждого устройства — свой ключ", "devices", 1),
    ("step2", "Шаг 2 из 4", "Установите приложение", "Бесплатное приложение из официального магазина", "download", 2),
    ("step3", "Шаг 3 из 4", "Добавьте профиль", "Одна кнопка — и настройки уже в приложении", "profile", 3),
    ("step4", "Шаг 4 из 4", "Включите VPN", "Нажмите кнопку подключения в приложении", "power", 4),
    ("done", "Готово", "Вы подключены", "Банки, Госуслуги и маркетплейсы работают напрямую", "done", 5),
    ("devices", "Кабинет", "Мои устройства", "Ключи, статусы и отключение", "list", None),
    ("docs", "Документы", "Тарифы и условия", "Цены, соглашение, конфиденциальность", "doc", None),
    ("help", "Поддержка", "Поможем разобраться", "Быстрые решения и связь с поддержкой", "help", None),
    ("key", "Ключ", "Ваш ключ доступа", "QR-код и ссылка для любого приложения", "key", None),
]

CSS = """
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:1280px;height:720px;overflow:hidden}
body{font-family:-apple-system,"SF Pro Display","Helvetica Neue",Arial,sans-serif;color:#fff;
 background:radial-gradient(900px 600px at 1010px 330px,#173A73 0%,#0E2850 38%,#0B1F3A 72%);position:relative}
.brand{position:absolute;left:72px;top:60px;display:flex;align-items:center;gap:18px}
.brand .k{width:62px;height:62px}.brand .w{height:40px}
.kicker{position:absolute;right:72px;top:70px;font-size:20px;font-weight:600;letter-spacing:3px;text-transform:uppercase;
 color:#78AAFF;border:2px solid rgba(120,170,255,.45);border-radius:40px;padding:10px 22px}
.kicker.ok{color:#5FD38F;border-color:rgba(95,211,143,.5)}
.text{position:absolute;left:72px;top:212px;width:700px}
h1{font-size:72px;line-height:1.04;font-weight:700;letter-spacing:-1.5px}
p{margin-top:22px;font-size:30px;line-height:1.3;color:#A9B8D2}
.icon{position:absolute;right:110px;top:150px;width:330px;height:330px;border-radius:50%;
 background:radial-gradient(circle at 50% 40%,#1D3D70,#132C52 70%);box-shadow:0 0 0 14px rgba(47,107,255,.10),0 0 90px rgba(47,107,255,.35);
 display:flex;align-items:center;justify-content:center}
.icon svg{width:230px;height:230px}
.track{position:absolute;left:72px;right:72px;bottom:58px;display:flex;align-items:flex-start}
.node{display:flex;flex-direction:column;align-items:center;width:150px;position:relative;z-index:2}
.dot{width:50px;height:50px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:23px;font-weight:700;
 border:3px solid #3A5175;color:#6E80A0;background:#0B1F3A}
.node span{margin-top:12px;font-size:20px;color:#6E80A0;font-weight:500}
.node.cur .dot{background:#2F6BFF;border-color:#2F6BFF;color:#fff;box-shadow:0 0 0 8px rgba(47,107,255,.25)}
.node.cur span{color:#fff;font-weight:700}
.node.ok .dot{background:#1E9E5A;border-color:#1E9E5A;color:#fff}
.node.ok span{color:#9FD9B7}
.line{flex:1;height:4px;margin-top:23px;background:#2A3F62;border-radius:2px;margin-left:-50px;margin-right:-50px;z-index:1}
.line.ok{background:#1E9E5A}
.hero h1{font-size:80px}
.chips{display:flex;gap:14px;margin-top:40px;flex-wrap:wrap;width:760px}
.chip{font-size:23px;padding:13px 22px;border-radius:30px;background:rgba(47,107,255,.16);border:2px solid rgba(120,170,255,.35);color:#D6E2F7}
.bigknot{position:absolute;right:96px;top:150px;width:380px;height:380px;filter:drop-shadow(0 0 60px rgba(47,107,255,.45))}
"""


def svg_file(name):
    with open(os.path.join(SRC, name), encoding="utf-8") as fh:
        return fh.read()


def brand(show_knot=True):
    knot = f'<div class="k">{svg_file("knot.svg")}</div>' if show_knot else ""
    return f'<div class="brand">{knot}<div class="w">{svg_file("wordmark-white.svg")}</div></div>'


def tracker(step):
    parts = []
    for i, label in enumerate(STEPS, 1):
        cls = "ok" if i < step or step == 5 else ("cur" if i == step else "")
        mark = "✓" if cls == "ok" else str(i)
        if i > 1:
            parts.append(f'<div class="line {"ok" if i <= step or step == 5 else ""}"></div>')
        parts.append(f'<div class="node {cls}"><div class="dot">{mark}</div><span>{label}</span></div>')
    return f'<div class="track">{"".join(parts)}</div>'


def page(body):
    return (f'<!doctype html><html><head><meta charset="utf-8"><style>{CSS}'
            '.k svg,.w svg,.bigknot svg{width:100%;height:100%}</style></head>'
            f'<body>{body}</body></html>')


def card_html(name, kicker, headline, subline, icon, step):
    text_top = "" if step else 'style="top:250px"'
    return page(brand() + f'<div class="kicker {"ok" if step == 5 else ""}">{kicker}</div>'
                f'<div class="text" {text_top}><h1>{headline}</h1><p>{subline}</p></div>'
                f'<div class="icon">{ICONS[icon]}</div>' + (tracker(step) if step else ""))


def hero_html(headline, subline, chips):
    chip_html = "".join(f'<div class="chip">{c}</div>' for c in chips)
    return page(brand(show_knot=False) + f'<div class="text hero" style="top:190px"><h1>{headline}</h1><p>{subline}</p>'
                f'<div class="chips">{chip_html}</div></div><div class="bigknot">{svg_file("knot.svg")}</div>')


HEROES = [
    ("welcome", "Добро пожаловать<br>в Nexo", "Защищённое соединение для телефона, компьютера и телевизора",
     ("Подключение за 2 минуты", "До 3 устройств", "Банки работают напрямую")),
    ("home", "Nexo", "Ваше защищённое соединение",
     ("Мои устройства", "Тарифы", "Поддержка")),
]


def render(name, html, out_dir):
    with tempfile.NamedTemporaryFile("w", suffix=".html", delete=False, encoding="utf-8") as fh:
        fh.write(html)
        src = fh.name
    out = os.path.join(out_dir, f"{name}.png")
    subprocess.run([CHROME, "--headless=new", "--disable-gpu", "--hide-scrollbars", "--force-device-scale-factor=1",
                    "--window-size=1280,720", f"--screenshot={out}", f"file://{src}"],
                   check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    os.unlink(src)
    return out


def main():
    for name, *rest in CARDS:
        print(render(name, card_html(name, *rest), HERE))
    for name, headline, subline, chips in HEROES:
        print(render(name, hero_html(headline, subline, chips), HERE))


if __name__ == "__main__":
    main()

