def page(title, body, status=200, headers=None):
    doc = f"""<!doctype html><html lang="ru"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer">
<meta name="theme-color" content="#060d1b"><meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="apple-mobile-web-app-title" content="{html.escape(BRAND_TITLE)}">
<link rel="apple-touch-icon" href="/web/icon.png"><link rel="manifest" href="/web/manifest.webmanifest">
<title>{html.escape(title)}</title><style>{STYLE}</style></head><body><main>{body}</main></body></html>"""
    return web.Response(text=doc, status=status, content_type="text/html", headers={
        "Cache-Control": "no-store", "X-Robots-Tag": "noindex, nofollow", "Referrer-Policy": "no-referrer",
        "X-Content-Type-Options": "nosniff", "X-Frame-Options": "DENY",
        "Content-Security-Policy": "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; "
                                   "img-src 'self' data:; media-src 'self'; base-uri 'none'; frame-ancestors 'none'; "
                                   "form-action 'self' https://pay.platega.io",
        **(headers or {})})


def logo(pill="", home="/app"):
    return (f'<div class="bar"><a class="brand" href="{home}"><img src="/web/icon.png" alt="">{html.escape(BRAND_TITLE)}</a>{pill}</div>')


FOOTER = ('<footer><a href="/docs/tariffs">Тарифы</a><a href="/docs/terms">Соглашение</a>'
          '<a href="/docs/privacy">Конфиденциальность</a><a href="/docs/support">Поддержка</a></footer>')
ICONS = {"ios": "📱", "android": "🤖", "macos": "💻", "windows": "🖥"}


def price(value: int) -> str:
    return f"{value:,} ₽".replace(",", " ")


def per_month(plan) -> int:
    return round(plan["price"] / (payments.DAYS[plan["key"]] / 30))


