async def handle_start(request):
    keys = _keys()
    db = request.app[keys.DATABASE_KEY]
    if not _allowed_start(request.remote or "unknown"):
        return page("Слишком много попыток", logo() + '<div class="card"><div class="title">Слишком много попыток</div>'
                    "<p>С этого адреса сегодня уже начинали подключение. Попробуйте завтра или с другой сети.</p></div>",
                    status=429)
    tg_id, token = db.create_web_user(TRIAL_DAYS)
    platform = detect_platform(request.headers.get("User-Agent", ""))
    if platform:
        await _create_device(request, tg_id, platform)
    raise web.HTTPSeeOther(f"/c/{token}?new=1" + (f"&p={platform}" if platform else ""))


async def _create_device(request, tg_id, platform):
    keys = _keys()
    service = DeviceService(nodes=list(request.app[keys.NODE_PROVIDER_KEY]()),
                            client_factory=request.app[keys.DEVICE_CLIENT_FACTORY_KEY])
    try:
        return await service.create(tg_id, "", "Web", PLATFORMS[platform], platform, f"web-{platform}")
    except DeviceError:
        return None


# ---------------------------------------------------------------- cabinet -------
def _user(request):
    db = request.app[_keys().DATABASE_KEY]
    user = db.get_user_by_web_token(request.match_info.get("token", ""))
    if not user:
        raise web.HTTPNotFound(text="Not found")
    return db, user


def _device_for(db, user, platform):
    rows = [d for d in db.list_devices(user["tg_id"]) if d["platform"] == platform and d["status"] == "active"]
    return rows[-1] if rows else None


def status_card(user):
    """Ring with the days left (full ring = 30 days) and the end date."""
    from datetime import datetime, timezone
    until = payments.active_until(user)
    if not until:
        return ('<div class="card status"><svg class="ring" viewBox="0 0 72 72"><circle cx="36" cy="36" r="31" fill="none" '
                'stroke="#2a1830" stroke-width="7"/><text x="36" y="42" text-anchor="middle" font-size="20" fill="#ff8aa0">!</text></svg>'
                '<div><h2>Доступ закончился</h2><p>Продлите — ключи заработают сразу после оплаты.</p>'
                '<a class="btn" href="#pay">Продлить</a></div></div>')
    days = max(1, (until - datetime.now(timezone.utc).replace(tzinfo=None)).days + 1)
    length = 194.8
    done = length * min(1, days / 30)
    word = "день" if days % 10 == 1 and days % 100 != 11 else "дня" if days % 10 in (2, 3, 4) and days % 100 not in (12, 13, 14) else "дней"
    return ('<div class="card status"><svg class="ring" viewBox="0 0 72 72">'
            '<circle cx="36" cy="36" r="31" fill="none" stroke="#16294a" stroke-width="7"/>'
            f'<circle cx="36" cy="36" r="31" fill="none" stroke="#2fd18b" stroke-width="7" stroke-linecap="round" '
            f'stroke-dasharray="{done:.1f} {length}" transform="rotate(-90 36 36)"/>'
            f'<text x="36" y="42" text-anchor="middle" font-size="19" font-weight="800" fill="#eef3ff">{days}</text></svg>'
            f'<div><h2>Доступ активен</h2><p>до {until:%d.%m.%Y} · осталось {days} {word}</p></div></div>')


async def handle_cabinet(request):
    db, user = _user(request)
    token = request.match_info["token"]
    base = request.app[_keys().PUBLIC_BASE_URL_KEY].rstrip("/")
    q = request.query
    flash = ""
    if q.get("check", "").isdigit():  # back from the payment page
        payment = db.get_payment(int(q["check"]))
        if payment and payment["tg_id"] == user["tg_id"]:
            try:
                payment, _ = await payments.check(payment)
            except payments.PaymentError:
                pass
            flash = ('<div class="flash">✅ Оплата получена, доступ продлён.</div>' if payment["status"] == "paid" else
                     '<div class="flash err">Оплата пока не поступила. Если вы уже оплатили — обновите страницу через минуту.</div>'
                     if payment["status"] == "pending" else '<div class="flash err">Оплата не прошла. Можно попробовать ещё раз.</div>')
            user = db.get_user(user["tg_id"])
    if q.get("new"):
        flash += ('<div class="flash">Готово! Это ваш личный кабинет. Сохраните ссылку на него — '
                  'кнопка «Скопировать ссылку» внизу.</div>')
    if q.get("err") == "device":
        flash += '<div class="flash err">Не удалось создать ключ. Попробуйте ещё раз через минуту.</div>'
    if q.get("err") == "pay":
        flash += '<div class="flash err">Не удалось создать оплату. Попробуйте ещё раз через минуту.</div>'

    until = payments.active_until(user)
    pill = (f'<span class="pill ok">Доступ до {until:%d.%m.%Y}</span>' if until else '<span class="pill off">Доступ закончился</span>')
    platform = q.get("p") if q.get("p") in dict(WEB_PLATFORMS) else detect_platform(request.headers.get("User-Agent", "")) or "ios"
    seg = "".join(f'<a class="{"on" if key == platform else ""}" href="?p={key}#setup"><i>{ICONS[key]}</i>{label}</a>'
                  for key, label in WEB_PLATFORMS)

    apps = catalog.apps_for(platform)
    store = q.get("store") if q.get("store") in catalog.STORE_APP else "ru"
    default_app = catalog.STORE_APP[store] if platform == "ios" else apps[0].key
    app = catalog.get_app(platform, q.get("app") or default_app)
    device = _device_for(db, user, platform)

    setup = f'<div class="card" id="setup"><div class="title">Подключить устройство</div><div class="seg">{seg}</div>'
    if platform == "ios":
        setup += ('<div class="seg two">'
                  f'<a class="{"on" if store != "other" else ""}" href="?p=ios&store=ru#setup">🇷🇺 Российский App Store</a>'
                  f'<a class="{"on" if store == "other" else ""}" href="?p=ios&store=other#setup">🌍 Другой страны</a></div>'
                  '<small>Если цены в App Store в рублях — у вас российский.</small>')
    if not device:
        setup += (f'<form method="post" action="/c/{token}/device?p={platform}">'
                  f'<button class="btn">Создать ключ для {html.escape(dict(WEB_PLATFORMS)[platform])}</button></form>'
                  '<small>Ключ появится за несколько секунд.</small>')
    else:
        link = import_link(app, platform, device, base)
        setup += (f'<div class="step"><span class="n">1</span><div><b>Установите {app.name}</b>'
                  f'<a class="btn" href="{html.escape(app.install[0][1], quote=True)}">Установить {app.name}</a>')
        if not app.auto_rules and app.importer:
            setup += '<div class="note">При первом запуске выберите язык «Русский» и страну «Россия» — так банки будут работать.</div>'
        setup += '</div></div>'
        if link:
            setup += (f'<div class="step"><span class="n">2</span><div><b>Добавьте ключ</b>'
                      f'<a class="btn" href="{html.escape(link, quote=True)}">Добавить ключ в {app.name}</a>'
                      '<small>Приложение откроется само и спросит подтверждение.</small></div></div>')
        else:
            setup += (f'<div class="step"><span class="n">2</span><div><b>Добавьте ключ по ссылке</b>'
                      f'<div class="link">{html.escape(base + "/sub/" + device["token"])}</div></div></div>')
        setup += (f'<div class="step"><span class="n">3</span><div><b>Включите</b>'
                  f'<p>{html.escape(catalog.POWER_ON[platform].format(app=app.name))}</p></div></div>')
        video = catalog.VIDEOS.get(platform, {}).get(app.key)
        if video and os.path.exists(os.path.join(ASSETS, "video", video)):
            setup += ('<small>Видео-инструкция · 1,5 минуты</small>'
                      f'<video src="/media/{video}" poster="/web/{os.path.splitext(video)[0]}-poster.jpg" controls playsinline preload="none"></video>')
        for label, key in catalog.SWITCH.get(platform, {}).get(app.key, []):
            setup += f'<a class="btn ghost" href="?p={platform}&store={store}&app={key}#setup">{html.escape(label)}</a>'
    setup += "</div>"

    active = [d for d in db.list_devices(user["tg_id"]) if d["status"] == "active"]
    devices = ""
    if active:
        rows = "".join(f'<div class="item"><span class="ico">{ICONS.get(d["platform"], "🔑")}</span><div><b>{html.escape(d["label"])}</b>'
                       f'<span>Ключ создан {html.escape(str(d.get("created_at") or "")[:10])}</span></div></div>' for d in active)
        devices = f'<div class="card"><div class="title">Мои устройства · {len(active)} из {user.get("device_limit") or 3}</div><div class="list">{rows}</div></div>'

    pay = '<div class="card" id="pay"><div class="title">Оплата</div>'
    if payments.enabled():
        full = payments.tariff("m1")["price"]
        pay += '<div class="tariffs">'
        for t in payments.paid_tariffs():
            months = payments.DAYS[t["key"]] // 30
            saving = round(100 * (1 - t["price"] / (full * months))) if months > 1 else 0
            badge = f'<span class="badge">−{saving}%</span>' if saving >= 20 else ""
            pay += (f'<form method="post" action="/c/{token}/pay?tariff={t["key"]}">'
                    f'<button class="tariff{" best" if badge else ""}"><span><span class="t">{t["title"]}{badge}</span>'
                    f'<span class="s">{price(per_month(t))} в месяц</span></span><span class="p">{price(t["price"])}</span></button></form>')
        pay += '</div><small>Новый срок добавляется к оставшемуся. СБП, карта или криптовалюта. Автоматического продления нет.</small>'
    else:
        pay += '<p>Оплата скоро появится.</p>'
    pay += "</div>"

    link = f"{base}/c/{token}"
    save = ('<div class="card"><div class="title">Ваш личный кабинет</div><p>По этой ссылке вы всегда вернётесь сюда — '
            'логина и пароля нет. Сохраните её в заметки или добавьте страницу на экран «Домой».</p>'
            f'<div class="link">{html.escape(link)}</div>'
            f'<button class="btn ghost" onclick="navigator.clipboard.writeText(\'{html.escape(link)}\')'
            '.then(()=>this.textContent=\'Скопировано ✓\')">Скопировать ссылку</button>'
            '<small>iPhone: кнопка «Поделиться» → «На экран „Домой“». Никому не пересылайте эту ссылку.</small></div>')
    tg = ('<div class="card"><div class="title">Telegram</div><p>Когда VPN включится, откроется и Telegram — там наш бот '
          f'<a href="https://t.me/{BOT_USERNAME}">@{BOT_USERNAME}</a> с подсказками и поддержкой.</p></div>')
    body = logo(pill, home=f"/c/{token}") + flash + status_card(user) + setup + devices + pay + save + tg + FOOTER
    return page(f"{BRAND_TITLE} — кабинет", body, headers={
        "Set-Cookie": f"{COOKIE}={token}; Max-Age=31536000; Path=/; Secure; HttpOnly; SameSite=Lax"})


