                                   "img-src 'self' data:; media-src 'self'; base-uri 'none'; frame-ancestors 'none'; "
                                   "form-action 'self' https://pay.platega.io",
        **(headers or {})})


def top(inner, home="/app", aux=("Тарифы", "/docs/tariffs")):
    return (f'<div class="top">{knot("#FFFFFF", "#2F6BFF", "#2F6BFF", "bg", "mark-bg")}'
            f'<div class="bar"><a class="brand" href="{home}">{knot("#FFFFFF", "#2F6BFF", "#2F6BFF", "br")}{html.escape(BRAND_TITLE.lower())}</a>'
            f'<a class="aux" href="{aux[1]}">{aux[0]}</a></div>{inner}</div>')


def sheet(inner, flat=False):
    return f'<div class="sheet"><div class="sheet-in{" flat" if flat else ""}">{inner}{FOOTER}</div></div>'


FOOTER = ('<footer><a href="/docs/tariffs">Тарифы</a><a href="/docs/terms">Соглашение</a>'
          '<a href="/docs/privacy">Конфиденциальность</a><a href="/docs/support">Поддержка</a></footer>')


def price(value: int) -> str:
    return f"{value:,} ₽".replace(",", " ")


def per_month(plan) -> int:
    return round(plan["price"] / (payments.DAYS[plan["key"]] / 30))


def logo(pill="", home="/app"):  # kept for small service pages
    return top("", home=home)


# ---------------------------------------------------------------- landing -------
async def handle_landing(request):
    db = request.app[_keys().DATABASE_KEY]
    token = request.cookies.get(COOKIE, "")
    if token and db.get_user_by_web_token(token):
        raise web.HTTPFound(f"/c/{token}")
    platform = detect_platform(request.headers.get("User-Agent", ""))
    device = dict(WEB_PLATFORMS).get(platform, "")
    cheapest = min(per_month(t) for t in payments.paid_tariffs())
    sample = (f'<div class="pass">{knot("#2F6BFF", "#FFFFFF", "#0B1F3A", "pk", "mk")}'
              f'<div class="head">Ключ {html.escape(BRAND_TITLE)}<span class="state on">готов к выдаче</span></div>'
              f'<p class="label">Пробный доступ</p><div class="big">{TRIAL_DAYS} дней бесплатно</div>'
              '<div class="sub">Австрия и Бразилия · до 3 устройств</div>'
              f'<div class="perf"></div><div class="stub"><span>{html.escape(device or "Телефон или компьютер")}</span>'
              '<span class="muted">банки — напрямую</span></div></div>')
    hero = ("<h1>Подключитесь за две минуты</h1>"
            '<p class="lead">Без регистрации и без Telegram — всё делается прямо на этой странице.</p>'
            '<form method="post" action="/app/start">'
            f'<button class="btn white">Начать{" на " + html.escape(device) if device else ""} →</button></form>'
            f'<p class="fine">Потом — от {cheapest} ₽ в месяц. Автоматических списаний нет.</p>' + sample)
    plans = "".join(f'<li><span>{t["title"]}<span class="s">{price(per_month(t))} в месяц</span></span>'
                    f'<span class="price">{price(t["price"])}</span></li>' for t in payments.paid_tariffs())
    body = (top(hero) + sheet(
        "<section><h2>Что будет дальше</h2><ol class=\"steps\">"
        "<li><b>Установите приложение</b><span class=\"muted\">Кнопка сразу откроет App Store или Google Play.</span></li>"
        "<li><b>Добавьте ключ одной кнопкой</b><span class=\"muted\">Копировать и вставлять ничего не нужно.</span></li>"
        "<li><b>Включите</b><span class=\"muted\">Одна кнопка в приложении. Банки и Госуслуги работают как обычно.</span></li></ol></section>"
        f'<section><h2>Сколько стоит</h2><ul class="rows">{plans}</ul></section>'
        "<section><h2>Уже подключались?</h2><p class=\"muted\">Откройте свою личную ссылку на кабинет — она была на странице "
        "после первого подключения. В этом же браузере кабинет откроется сам.</p></section>"))
    return page(f"{BRAND_TITLE} — подключение", body)


async def handle_start(request):
    keys = _keys()
    db = request.app[keys.DATABASE_KEY]
    if not _allowed_start(request.remote or "unknown"):
        return page("Слишком много попыток", top("<h1>Слишком много попыток</h1>") + sheet(
            "<section><p>С этого адреса сегодня уже начинали подключение. Попробуйте завтра или из другой сети — "
            "например, с мобильного интернета вместо Wi-Fi.</p></section>", flat=True), status=429)
    tg_id, token = db.create_web_user(TRIAL_DAYS)
    platform = detect_platform(request.headers.get("User-Agent", ""))
    if platform:
        await _create_device(request, tg_id, platform)
    raise web.HTTPSeeOther(f"/c/{token}?new=1" + (f"&p={platform}" if platform else ""))


async def _create_device(request, tg_id, platform):
    keys = _keys()
    service = DeviceService(nodes=list(request.app[keys.NODE_PROVIDER_KEY]()),
                            client_factory=request.app[keys.DEVICE_CLIENT_FACTORY_KEY])
    try:
        return await service.create(tg_id, "", "Web", PLATFORMS[platform], platform, f"web-{platform}")
    except DeviceError:
        return None


# ---------------------------------------------------------------- cabinet -------
def _user(request):
    db = request.app[_keys().DATABASE_KEY]
    user = db.get_user_by_web_token(request.match_info.get("token", ""))
    if not user:
        raise web.HTTPNotFound(text="Not found")
    return db, user


def _device_for(db, user, platform):
    rows = [d for d in db.list_devices(user["tg_id"]) if d["platform"] == platform and d["status"] == "active"]
    return rows[-1] if rows else None


def key_pass(user, active_count):
    """The personal key as a ticket: status, end date, days left (a full bar is 30 days), devices."""
    from datetime import datetime, timezone
    until = payments.active_until(user)
    limit = user.get("device_limit") or 3
    head = f'<div class="head">Ключ {html.escape(BRAND_TITLE)}'
    if until:
        days = max(1, (until - datetime.now(timezone.utc).replace(tzinfo=None)).days + 1)
        body = (f'{head}<span class="state on">Активен</span></div><p class="label">Доступ до</p>'
                f'<div class="big">{day_month(until)}</div>'
                f'<div class="sub">осталось {days} {plural(days, "день", "дня", "дней")} · до {until:%d.%m.%Y}</div>'
                f'<div class="meter"><i style="width:{min(100, round(days / 30 * 100))}%"></i></div>')
    else:
        body = (f'{head}<span class="state off">Не активен</span></div><p class="label">Доступ закончился</p>'
