def page(title, body, status=200, headers=None):
    doc = f"""<!doctype html><html lang="ru"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer">
<meta name="theme-color" content="#2F6BFF"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="apple-mobile-web-app-title" content="{html.escape(BRAND_TITLE)}">
<link rel="apple-touch-icon" href="/web/icon.png"><link rel="manifest" href="/web/manifest.webmanifest">
<link rel="preload" href="/web/fonts/unbounded-cyrillic.woff2" as="font" type="font/woff2" crossorigin>
<script>document.documentElement.className='js'</script>
<title>{html.escape(title)}</title><style>{STYLE}</style></head><body>{body}</body></html>"""
    return web.Response(text=doc, status=status, content_type="text/html", headers={
        "Cache-Control": "no-store", "X-Robots-Tag": "noindex, nofollow", "Referrer-Policy": "no-referrer",
        "X-Content-Type-Options": "nosniff", "X-Frame-Options": "DENY",
        "Content-Security-Policy": "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; font-src 'self'; "
                                   "img-src 'self' data:; media-src 'self'; base-uri 'none'; frame-ancestors 'none'; "
                                   "form-action 'self' https://pay.platega.io https://t.me",
        **(headers or {})})


def appbar(home="/app", right=""):
    return (f'<header class="appbar"><a class="brand" href="{home}">{knot("#FFFFFF", "#2F6BFF", "#2F6BFF", "br")}'
            f'{html.escape(BRAND_TITLE.lower())}</a>{right}</header>')


def row(href, icon, title, sub="", external=False):
    target = ' target="_blank" rel="noreferrer"' if external else ""
    return (f'<a class="row" href="{href}"{target}><span class="ic">{ICONS[icon]}</span><span class="tx"><b>{title}</b>'
            f'{f"<span>{sub}</span>" if sub else ""}</span><span class="chev">›</span></a>')


DOC_ROWS = (row("/docs/tariffs", "doc", "Тарифы") + row("/docs/terms", "doc", "Пользовательское соглашение")
            + row("/docs/privacy", "doc", "Политика конфиденциальности") + row("/docs/support", "chat", "Поддержка"))


def price(value: int) -> str:
    return f"{value:,} ₽".replace(",", " ")


def per_month(plan) -> int:
    return round(plan["price"] / (payments.DAYS[plan["key"]] / 30))


def simple(title, inner, back="/app"):
    """A plain app screen: app bar, large title, one white group (documents, errors)."""
    return (f'<div class="app">{appbar(back)}<div class="screen" style="display:block"><h1 class="large">{title}</h1>'
            f'<div class="group pad">{inner}</div><a class="btn quiet" href="{back}">Назад</a></div></div>')


# ---------------------------------------------------------------- landing -------
async def handle_landing(request):
    db = request.app[_keys().DATABASE_KEY]
    token = request.cookies.get(COOKIE, "")
    if token and db.get_user_by_web_token(token):
        raise web.HTTPFound(f"/c/{token}")
    platform = detect_platform(request.headers.get("User-Agent", ""))
    device = dict(WEB_PLATFORMS).get(platform, "")
    cheapest = min(per_month(t) for t in payments.paid_tariffs())
    sample = (f'<div class="pass">{knot("#2F6BFF", "#FFFFFF", "#0B1F3A", "pk", "mk")}'
              f'<div class="head">Ключ {html.escape(BRAND_TITLE)}<span class="state on">готов к выдаче</span></div>'
              f'<p class="label">Пробный доступ</p><div class="big">{TRIAL_DAYS} дней бесплатно</div>'
              '<div class="sub">Австрия и Бразилия · до 3 устройств</div>'
              f'<div class="perf"></div><div class="stub"><span>{html.escape(device or "Телефон или компьютер")}</span>'
              '<span class="muted">банки — напрямую</span></div></div>')
    body = (f'<div class="onb">{knot("#FFFFFF", "#2F6BFF", "#2F6BFF", "bg", "mark-bg")}'
            f'<div class="brand" style="position:relative">{knot("#FFFFFF", "#2F6BFF", "#2F6BFF", "br")}{html.escape(BRAND_TITLE.lower())}</div>'
            "<h1>Подключитесь за две минуты</h1>"
            '<p class="lead">Без регистрации и без Telegram — всё прямо здесь.</p>' + sample +
            '<ul class="ticks"><li>Установите приложение — кнопка откроет App Store или Google Play</li>'
            "<li>Добавьте ключ одной кнопкой</li><li>Включите — банки и Госуслуги работают как обычно</li></ul></div>"
            '<div class="dock"><div class="dock-in"><form method="post" action="/app/start">'
            f'<button class="btn">Начать{" на " + html.escape(device) if device else ""}</button></form>'
            f'<small>Потом — от {cheapest} ₽ в месяц, без автосписаний. Уже подключались? Откройте свою личную ссылку.</small>'
            '<small><a href="/docs/tariffs">Тарифы</a> · <a href="/docs/terms">Соглашение</a> · <a href="/docs/privacy">Конфиденциальность</a></small>'
            "</div></div>")
    return page(f"{BRAND_TITLE} — подключение", body)


async def handle_start(request):
    keys = _keys()
    db = request.app[keys.DATABASE_KEY]
    if not _allowed_start(request.remote or "unknown"):
        return page("Слишком много попыток", simple("Слишком много попыток",
                    "<p>С этого адреса сегодня уже начинали подключение. Попробуйте завтра или из другой сети — "
                    "например, с мобильного интернета вместо Wi-Fi.</p>"), status=429)
    tg_id, token = db.create_web_user(TRIAL_DAYS)
    platform = detect_platform(request.headers.get("User-Agent", ""))
    if platform:
        await _create_device(request, tg_id, platform)
    raise web.HTTPSeeOther(f"/c/{token}?new=1" + (f"&p={platform}" if platform else "") + "#setup")


def _service(request):
    keys = _keys()
    return DeviceService(nodes=list(request.app[keys.NODE_PROVIDER_KEY]()), client_factory=request.app[keys.DEVICE_CLIENT_FACTORY_KEY])


async def _create_device(request, tg_id, platform):
    try:
        return await _service(request).create(tg_id, "", "Web", PLATFORMS[platform], platform, f"web-{platform}")
    except DeviceError:
        return None


# ---------------------------------------------------------------- cabinet -------
def _user(request):
    db = request.app[_keys().DATABASE_KEY]
    user = db.get_user_by_web_token(request.match_info.get("token", ""))
    if not user:
        raise web.HTTPNotFound(text="Not found")
    return db, user


def _device_for(db, user, platform):
    rows = [d for d in db.list_devices(user["tg_id"]) if d["platform"] == platform and d["status"] == "active"]
    return rows[-1] if rows else None


def days_left(until):
    from datetime import datetime, timezone
    return max(1, (until - datetime.now(timezone.utc).replace(tzinfo=None)).days + 1)


def key_pass(user, active_count):
    """The personal key as a ticket: status, end date, days left (a full bar is 30 days), devices."""
    until = payments.active_until(user)
    limit = user.get("device_limit") or 3
    head = f'<div class="head">Ключ {html.escape(BRAND_TITLE)}'
    if until:
        days = days_left(until)
        state = '<span class="state soon">Заканчивается</span>' if days <= 3 else '<span class="state on">Активен</span>'
        body = (f'{head}{state}</div><p class="label">Доступ до</p>'
                f'<div class="big">{day_month(until)}</div>'
                f'<div class="sub">осталось {days} {plural(days, "день", "дня", "дней")} · до {until:%d.%m.%Y}</div>'
                f'<div class="meter"><i style="width:{min(100, round(days / 30 * 100))}%"></i></div>')
    else:
        body = (f'{head}<span class="state off">Не активен</span></div><p class="label">Доступ закончился</p>'
                '<div class="big">Продлите</div><div class="sub">Ключи заработают сразу после оплаты.</div>')
    return (f'<div class="pass">{knot("#2F6BFF", "#FFFFFF", "#0B1F3A", "pk", "mk")}{body}<div class="perf"></div>'
            f'<div class="stub"><span>Устройств: {active_count} из {limit}</span><a href="#pay">Продлить →</a></div></div>')


async def handle_cabinet(request):
    db, user = _user(request)
    token = request.match_info["token"]
    base = request.app[_keys().PUBLIC_BASE_URL_KEY].rstrip("/")
    q = request.query
    flash = ""
    if q.get("check", "").isdigit():  # back from the payment page
        payment = db.get_payment(int(q["check"]))
        if payment and payment["tg_id"] == user["tg_id"]:
            try:
                payment, _ = await payments.check(payment, service=_service(request))
            except payments.PaymentError:
                pass
            flash = ('<div class="flash">Оплата получена, доступ продлён.</div>' if payment["status"] == "paid" else
                     '<div class="flash err">Оплата пока не поступила. Если вы уже оплатили — обновите страницу через минуту.</div>'
                     if payment["status"] == "pending" else '<div class="flash err">Оплата не прошла, деньги не списаны. Можно попробовать ещё раз.</div>')
            user = db.get_user(user["tg_id"])
    if q.get("new"):
        flash += ('<div class="flash">Ключ готов. Это ваш личный кабинет — сохраните ссылку на него: вкладка «Ещё» → '
                  '«Скопировать ссылку».</div>')
    if q.get("err") == "device":
        flash += '<div class="flash err">Ключ не создался: сервер не ответил. Попробуйте ещё раз через минуту.</div>'
    if q.get("err") == "pay":
        flash += '<div class="flash err">Страница оплаты не открылась. Попробуйте ещё раз через минуту.</div>'

    until = payments.active_until(user)
    active = [d for d in db.list_devices(user["tg_id"]) if d["status"] == "active"]
    chip = ('<span class="chip off"><i></i>Не активен</span>' if not until else
            '<span class="chip soon"><i></i>Заканчивается</span>' if days_left(until) <= 3 else '<span class="chip"><i></i>Активен</span>')

    # -- home
    devices = "".join(row("#setup", "phone", html.escape(d["label"]), f'ключ выдан {html.escape(str(d.get("created_at") or "")[:10])}')
                      for d in active)
    home = (f'<section class="screen" id="home"><div class="hero" style="margin:0 -16px">{knot("#FFFFFF", "#2F6BFF", "#2F6BFF", "bg", "mark-bg")}'
            f'{key_pass(user, len(active))}</div>{flash}<div class="cap">Быстрые действия</div><div class="tiles">'
            f'<a class="tile primary" href="#setup"><span class="ic">{ICONS["setup"]}</span><b>Подключить устройство</b></a>'
            f'<a class="tile" href="#pay"><span class="ic">{ICONS["pay"]}</span><b>Продлить доступ</b></a>'
            f'<a class="tile" href="#more"><span class="ic">{ICONS["link"]}</span><b>Ссылка на кабинет</b></a>'
            f'<a class="tile" href="/docs/support"><span class="ic">{ICONS["chat"]}</span><b>Поддержка</b></a></div>'
            + (f'<div class="cap">Мои устройства</div><div class="group">{devices}</div>' if devices else "") + "</section>")

    # -- setup
    platform = q.get("p") if q.get("p") in dict(WEB_PLATFORMS) else detect_platform(request.headers.get("User-Agent", "")) or "ios"
    name = dict(WEB_PLATFORMS)[platform]
    seg = "".join(f'<a class="{"on" if key == platform else ""}" href="?p={key}#setup">{label}</a>' for key, label in WEB_PLATFORMS)
    apps = catalog.apps_for(platform)
    store = q.get("store") if q.get("store") in catalog.STORE_APP else "ru"
    default_app = catalog.STORE_APP[store] if platform == "ios" else apps[0].key
    app = catalog.get_app(platform, q.get("app") or default_app)
    device = _device_for(db, user, platform)
    setup = f'<section class="screen" id="setup"><h1 class="large">Подключение</h1><div class="seg">{seg}</div>'
    if platform == "ios":
        setup += ('<div class="seg small">'
                  f'<a class="{"on" if store != "other" else ""}" href="?p=ios&store=ru#setup">Российский App Store</a>'
                  f'<a class="{"on" if store == "other" else ""}" href="?p=ios&store=other#setup">Другой страны</a></div>')
    setup += '<div class="group pad">'
    if not until:
        setup += ('<div class="hint" style="margin:0">Срок доступа закончился — VPN на ваших устройствах отключён. '
                  'Продлите во вкладке «Оплата»: ключи заработают сразу, настраивать заново не нужно.</div>'
                  '<a class="btn" href="#pay" style="margin-top:12px">Продлить</a>')
    elif not device:
        setup += (f'<p class="muted" style="margin-top:0">Для {html.escape(name)} ещё нет ключа.</p>'
                  f'<form method="post" action="/c/{token}/device?p={platform}"><button class="btn">Создать ключ для {html.escape(name)}</button></form>'
                  '<p class="muted">Ключ появится через несколько секунд.</p>')
    else:
        link = import_link(app, platform, device, base)
        setup += (f'<ol class="steps"><li><b>Установите {app.name}</b>'
                  f'<a class="btn" href="{html.escape(app.install[0][1], quote=True)}">Установить {app.name}</a>')
        if not app.auto_rules and app.importer:
            setup += '<div class="hint">При первом запуске выберите язык «Русский» и страну «Россия» — так банки будут работать.</div>'
        setup += '</li>'
        if link:
            setup += (f'<li><b>Добавьте ключ</b><a class="btn" href="{html.escape(link, quote=True)}">Добавить ключ в {app.name}</a>'
                      '<p class="muted">Приложение откроется само и спросит подтверждение.</p></li>')
        else:
            setup += (f'<li><b>Добавьте ключ по ссылке</b><div class="linkbox"><code>{html.escape(base + "/sub/" + device["token"])}</code></div></li>')
        setup += f'<li><b>Включите</b><p class="muted">{html.escape(catalog.POWER_ON[platform].format(app=app.name))}</p></li>'
        if user["tg_id"] < 0:  # right after the VPN works, Telegram opens too: join the accounts then
            setup += (f'<li><b>Подключите Telegram</b><p class="muted">VPN включён — Telegram тоже заработал. Откройте наш бот: '
                      'устройства, срок и оплата станут общими, и он напомнит, когда пора продлить.</p>'
                      f'<form method="post" action="/c/{token}/telegram"><button class="btn quiet">Подключить Telegram</button></form></li>')
        setup += '</ol>'
    setup += '</div>'
    if until and device:
        video = catalog.VIDEOS.get(platform, {}).get(app.key)
        if video and os.path.exists(os.path.join(ASSETS, "video", video)):
            setup += ('<div class="cap">Видео · 1,5 минуты</div>'
                      f'<video src="/media/{video}" poster="/web/{os.path.splitext(video)[0]}-poster.jpg" controls playsinline preload="none"></video>')
        switches = "".join(row(f"?p={platform}&store={store}&app={key}#setup", "phone", html.escape(label))
                           for label, key in catalog.SWITCH.get(platform, {}).get(app.key, []))
        if switches:
            setup += f'<div class="cap">Не получается?</div><div class="group">{switches}</div>'
    setup += "</section>"

    # -- pay
    pay = '<section class="screen" id="pay"><h1 class="large">Оплата</h1>'
    if payments.enabled():
        full = payments.tariff("m1")["price"]
        pay += '<div class="group">'
        for t in payments.paid_tariffs():
            months = payments.DAYS[t["key"]] // 30
            saving = round(100 * (1 - t["price"] / (full * months))) if months > 1 else 0
            tag = f'<span class="tag">−{saving}%</span>' if saving >= 20 else ""
            pay += (f'<form method="post" action="/c/{token}/pay?tariff={t["key"]}"><button class="plan">'
                    f'<span class="t">{t["title"]}{tag}<span class="s">{price(per_month(t))} в месяц</span></span>'
                    f'<span class="price">{price(t["price"])}</span><span class="go">→</span></button></form>')
        pay += ('</div><p class="muted" style="margin:0 4px">Новый срок добавляется к оставшемуся. СБП, карта или криптовалюта. '
                'Автоматических списаний нет.</p>')
    else:
        pay += '<div class="group pad"><p class="muted">Оплата скоро появится.</p></div>'
    pay += "</section>"

    # -- more
    link = f"{base}/c/{token}"
    linked_step = bool(device) and until and user["tg_id"] < 0
    if linked_step:
