    while (context != null) {
      final route = ModalRoute.of(context);
      if (route is AlertHostRoute) {
        final host = route.navigator;
        if (host != null && host.mounted) {
          return host.context;
        }
        break;
      }
      context = route?.navigator?.context;
    }
    return rootNavigatorKey.currentContext!;
