.screen{padding:0 16px}.js .screen{display:none}.js .screen.on{display:block}
.large{font:600 27px/1.15 Unbounded,sans-serif;letter-spacing:-.015em;margin:22px 4px 14px}
.group{background:var(--paper);border-radius:20px;padding:6px 16px;margin:0 0 14px;box-shadow:0 1px 2px rgba(11,31,58,.05)}
.group.pad{padding:16px}
.cap{font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--slate);margin:18px 4px 8px}
.row{display:flex;align-items:center;gap:12px;padding:13px 0;color:var(--ink);text-decoration:none}
.row+.row{border-top:1px solid var(--line)}.row .tx{flex:1;min-width:0}.row .tx b{display:block;font-weight:700}
.row .tx span{display:block;font-size:13px;color:var(--slate)}.row .chev{color:#A7B3C8;font-size:20px;line-height:1}
.ic{flex:none;width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:var(--mist);color:var(--blue)}
.ic svg,.tile svg,.tabbar svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.tiles{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:-2px 0 14px}
.tile{background:var(--paper);border-radius:20px;padding:16px;color:var(--ink);text-decoration:none;box-shadow:0 1px 2px rgba(11,31,58,.05);
 display:flex;flex-direction:column;gap:22px;min-height:112px;transition:transform .12s}
.tile:active,.row:active{transform:scale(.98)}
.tile .ic{background:#E8EFFF}.tile b{font-weight:800;font-size:15px;line-height:1.25}
.tile.primary{background:var(--ink);color:#fff}.tile.primary .ic{background:rgba(255,255,255,.12);color:#fff}
.btn{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;min-height:52px;border:0;border-radius:14px;padding:14px 18px;
 font:800 16px/1.2 Manrope,sans-serif;text-decoration:none;cursor:pointer;background:var(--blue);color:#fff;transition:transform .12s}
.btn:active{transform:scale(.985)}.btn:disabled{opacity:.7}.btn.white{background:#fff;color:var(--ink)}.btn.quiet{background:var(--mist);color:var(--ink)}
.btn:focus-visible,.tile:focus-visible,.row:focus-visible,.tabbar a:focus-visible{outline:3px solid #9DB8FF;outline-offset:2px}
.muted{color:var(--slate);font-size:14px}p{margin:6px 0}
.pass{position:relative;background:#fff;color:var(--ink);border-radius:18px;padding:16px 18px 14px;box-shadow:0 16px 36px rgba(11,31,58,.22);
 margin-top:8px;animation:rise .6s cubic-bezier(.2,.8,.2,1) both}
@keyframes rise{from{transform:translateY(18px)}}
@media (prefers-reduced-motion:reduce){.pass{animation:none}.btn,.tile,.row{transition:none}}
.pass .head{display:flex;justify-content:space-between;align-items:center;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--slate)}
.state{display:inline-flex;align-items:center;gap:6px;letter-spacing:.02em;text-transform:none;font-size:13px}
.state::before{content:"";width:8px;height:8px;border-radius:50%;background:currentColor}
.state.on{color:var(--green)}.state.off{color:var(--red)}.state.soon{color:var(--amber)}
.pass .label{margin:12px 0 0;font-size:13px;color:var(--slate)}.pass .big{font:600 29px/1.08 Unbounded,sans-serif;margin:2px 0 4px}
.pass .sub{font-size:14px;color:var(--slate)}
.meter{height:6px;border-radius:6px;background:var(--mist);margin:12px 0 0;overflow:hidden}.meter i{display:block;height:100%;background:var(--blue);border-radius:6px}
.perf{position:relative;margin:14px -18px 10px;border-top:2px dashed var(--line)}
.perf::before,.perf::after{content:"";position:absolute;top:-11px;width:20px;height:20px;border-radius:50%;background:var(--blue)}
.perf::before{left:-10px}.perf::after{right:-10px}
.stub{display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:14px;font-weight:700}.stub a{text-decoration:none;font-weight:800}
.pass .mk{position:absolute;right:16px;top:42px;width:46px;height:46px}
.seg{display:flex;background:#E4EAF3;border-radius:12px;padding:3px;gap:3px;margin:0 0 12px}
.seg a{flex:1;min-width:0;text-align:center;padding:9px 2px;border-radius:10px;color:var(--slate);font-weight:700;font-size:14px;text-decoration:none;
 white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.seg a.on{background:#fff;color:var(--ink);box-shadow:0 1px 3px rgba(11,31,58,.16)}
.seg.small a{font-size:13px;padding:7px 2px}
ol.steps{list-style:none;margin:4px 0 0;padding:0;counter-reset:s}
ol.steps li{position:relative;padding:4px 0 20px 46px;counter-increment:s}
ol.steps li::before{content:counter(s);position:absolute;left:0;top:2px;width:30px;height:30px;border-radius:50%;background:var(--ink);color:#fff;
 font:600 13px/30px Unbounded,sans-serif;text-align:center}
ol.steps li::after{content:"";position:absolute;left:14px;top:38px;bottom:4px;width:2px;background:var(--line)}
ol.steps li:last-child{padding-bottom:6px}ol.steps li:last-child::after{display:none}
ol.steps b{display:block;font-size:16px;margin:3px 0 10px}ol.steps .muted{margin-top:6px}
.hint{border-left:3px solid var(--blue);background:var(--mist);padding:10px 12px;border-radius:0 10px 10px 0;font-size:14px;margin:10px 0 0}
video{display:block;width:100%;aspect-ratio:9/16;max-height:70vh;object-fit:contain;background:var(--ink);border-radius:16px}
.plan{display:flex;align-items:center;gap:12px;width:100%;background:none;border:0;padding:14px 0;color:var(--ink);cursor:pointer;text-align:left;font:inherit}
form+form .plan{border-top:1px solid var(--line)}form{margin:0}
.plan .t{flex:1;font-weight:800}.plan .t span.s{display:block;font-weight:500;font-size:13px;color:var(--slate)}
.price{font:600 16px Unbounded,sans-serif;white-space:nowrap}
.go{flex:none;width:34px;height:34px;border-radius:50%;background:var(--blue);color:#fff;display:grid;place-items:center;font-size:17px}
.tag{display:inline-block;margin-left:6px;font-size:11px;font-weight:800;color:var(--green);background:#E3F6EC;border-radius:6px;padding:2px 6px;vertical-align:2px}
.linkbox{display:flex;gap:8px;align-items:center;background:var(--mist);border-radius:12px;padding:6px 6px 6px 12px;margin:10px 0 6px}
.linkbox code{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font:600 13px/1 Manrope,sans-serif;color:var(--slate)}
.linkbox button{border:0;background:var(--ink);color:#fff;border-radius:9px;padding:11px 12px;font:800 13px Manrope,sans-serif;cursor:pointer;white-space:nowrap}
.flash{border-radius:16px;padding:12px 14px;margin:14px 0 0;font-weight:700;font-size:15px;background:#E3F6EC;color:#0B5E3B}
.flash.err{background:#FDECEC;color:#8E1F24}.flash.soon{background:#FFF3DC;color:#7A4B00}.flash .btn{margin-top:10px}
.linkbox.access{flex-wrap:wrap}.linkbox.access code{flex:9 0 auto;overflow:visible;font:800 19px/1.2 Manrope,sans-serif;color:var(--ink);letter-spacing:.04em;font-variant-numeric:tabular-nums}
.linkbox.access button{flex:1 0 auto}
.field{display:block;width:100%;min-height:52px;border:1.5px solid var(--line);border-radius:14px;padding:12px 14px;margin:10px 0 12px;background:#fff;color:var(--ink);
 font:800 19px Manrope,sans-serif;letter-spacing:.04em;text-align:center}
.field:focus-visible{outline:3px solid #9DB8FF;outline-offset:2px}
.tabbar{position:fixed;left:0;right:0;bottom:0;z-index:30;display:flex;justify-content:center;background:rgba(255,255,255,.92);
 -webkit-backdrop-filter:saturate(180%) blur(18px);backdrop-filter:saturate(180%) blur(18px);border-top:1px solid var(--line);padding-bottom:var(--bottom)}
.tabbar nav{display:flex;width:100%;max-width:520px}
.tabbar a{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;padding:9px 0 8px;color:#8A97AD;text-decoration:none;font-size:11px;font-weight:700}
.tabbar a.on{color:var(--blue)}.tabbar svg{width:24px;height:24px}
.onb{position:fixed;inset:0;background:var(--blue);color:#fff;overflow-y:auto;overflow-x:hidden;overscroll-behavior:none;
 padding:calc(14px + var(--top)) max(20px,calc(50% - 240px)) calc(160px + var(--bottom))}
.onb h1{font:600 30px/1.1 Unbounded,sans-serif;letter-spacing:-.015em;margin:26px 0 10px;position:relative}
.onb .lead{color:rgba(255,255,255,.88);margin:0 0 22px;position:relative}
.ticks{list-style:none;padding:0;margin:22px 0 0;position:relative}
.ticks li{display:flex;gap:10px;align-items:flex-start;padding:7px 0;font-weight:600}
.ticks li::before{content:"✓";flex:none;width:22px;height:22px;border-radius:50%;background:rgba(255,255,255,.18);display:grid;place-items:center;font-size:12px;font-weight:800}
.dock{position:fixed;left:0;right:0;bottom:0;z-index:30;background:#fff;border-radius:24px 24px 0 0;padding:16px 20px calc(14px + var(--bottom));
