"""AuraVPN — 3X-UI API Client"""

import aiohttp
import json
import ssl
import uuid
from runtime_config import get_nodes, get_panel
from vpn_service import build_vless_uri, build_xui_client


class XUIClient:
    def __init__(self, server_key: str = "vienna"):
        panel = get_panel(server_key)
        try:
            self.node = next(node for node in get_nodes() if node.key == server_key)
        except StopIteration as exc:
            raise KeyError(f"unknown VPN node: {server_key}") from exc
        self.base_url = panel.base_url
        self.username = panel.username
        self.inbound_id = panel.inbound_id
        self.ca_file = panel.ca_file
        self.insecure_tls = panel.insecure_tls
        self.session_cookie = None

    def _ssl_context(self):
        ctx = ssl.create_default_context()
        if self.insecure_tls:
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            return ctx
        if self.ca_file:
            ctx.load_verify_locations(cafile=self.ca_file)
        return ctx

    async def login(self) -> bool:
        headers = {
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36",
            "X-Requested-With": "XMLHttpRequest",
            "Referer": f"{self.base_url}/",
            "Origin": self.base_url.split("/")[0] + "//" + self.base_url.split("/")[2] if "://" in self.base_url else self.base_url,
            "Content-Type": "application/x-www-form-urlencoded",
        }
        async with aiohttp.ClientSession() as session:
            try:
                async with session.post(
                    f"{self.base_url}/login",
                    headers=headers,
                    ssl=self._ssl_context(),
                    timeout=aiohttp.ClientTimeout(total=12),
                ) as resp:
                    if resp.status != 200:
                        return False
                    text = await resp.text()
                    try:
                        result = json.loads(text)
                    except Exception:
                        return False
                    if result.get("success"):
                        cookies = resp.cookies
                        c = cookies.get("3x-ui")
                        if c:
                            self.session_cookie = c.value
                        return True
            except Exception:
                return False
        return False

    async def _request(self, method: str, path: str, data=None):
        if not self.session_cookie:
            ok = await self.login()
            if not ok:
                return {"success": False, "error": "login failed"}

        cookies = {"3x-ui": self.session_cookie} if self.session_cookie else {}
        try:
            async with aiohttp.ClientSession(cookies=cookies) as session:
                timeout = aiohttp.ClientTimeout(total=15)
                if method == "GET":
                    async with session.get(
                        f"{self.base_url}{path}", ssl=self._ssl_context(), timeout=timeout
                    ) as resp:
                        return await resp.json()
                else:
                    async with session.post(
                        f"{self.base_url}{path}",
                        json=data,
                        ssl=self._ssl_context(),
                        timeout=timeout
                    ) as resp:
                        return await resp.json()
        except Exception as e:
            return {"success": False, "error": str(e)}

