import Foundation
import NexoCore

enum NexoShared {
    static let appGroup = "group.app.nexo.vpn"
    static let tunnelBundleSuffix = ".PacketTunnel"

    static var containerURL: URL {
        guard let url = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: appGroup) else {
            fatalError("App Group \(appGroup) is missing from the entitlements")
        }
        return url
    }

    // The Core's home: profiles, providers and spilled responses must be readable by both processes.
    static var homeURL: URL {
        let url = containerURL.appendingPathComponent("home", isDirectory: true)
        try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url
    }

    static var sharedStateURL: URL {
        containerURL.appendingPathComponent("shared_state.json")
    }

    static func initParams() -> String {
        let params: [String: Any] = ["home-dir": homeURL.path, "version": 0]
        let data = try! JSONSerialization.data(withJSONObject: params)
        return String(decoding: data, as: UTF8.self)
    }
}

final class CoreResultHandler: NSObject, NexoMobileResultHandlerProtocol {
    private let block: (Data?) -> Void

    init(_ block: @escaping (Data?) -> Void) {
        self.block = block
    }

    func onResult(_ data: Data?) throws {
        block(data)
    }
}

enum CoreRouting {
    // Calls that change what the running tunnel does go to its Core as well as the app's.
    static let mirrored: Set<String> = [
        "setupConfig", "updateConfig", "changeProxy", "closeConnections", "closeConnection",
        "resetConnections", "clearDnsCache", "updateExternalProvider", "sideLoadExternalProvider",
        "updateGeoData",
    ]

    // Only the tunnel's Core carries traffic, so these are answered by it alone while it runs.
    static let tunnelOnly: Set<String> = [
        "getTraffic", "getTotalTraffic", "resetTraffic", "getConnections", "getConnectionCount",
        "outboundIp", "getMemoryStats",
    ]

    static func methodName(of payload: String) -> String? {
        guard let data = payload.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else { return nil }
        return object["method"] as? String
    }
}

import NetworkExtension
import NexoCore

private let ipv4Address = "198.18.0.1"
private let ipv4Mask = "255.255.255.252"
private let ipv6Address = "fdfe:dcba:9876::1"
private let dns4 = "198.18.0.2"
private let dns6 = "fdfe:dcba:9876::2"
private let defaultMtu = 9000

private struct VpnOptions: Decodable {
    let ipv6: Bool
    let dnsHijacking: Bool
    let stack: String
    let routeAddress: [String]
    let mtu: Int?
    let congestionController: String?
}

private struct SharedState: Decodable {
    let vpnOptions: VpnOptions?
}

enum TunnelError: LocalizedError {
    case message(String)

    var errorDescription: String? {
        switch self {
        case .message(let text): return text
        }
    }
}

final class TunCallbacks: NSObject, NexoMobileTunHandlerProtocol {
    // Sockets the extension opens never re-enter its own tunnel on iOS.
    func protect(_ fd: Int32, ret0_: UnsafeMutablePointer<ObjCBool>?) throws {
        ret0_?.pointee = true
    }

    func resolvePackage(_ uid: Int32) throws -> String {
        ""
    }

    func resolveUid(_ protocol: Int32, source: String?, target: String?, ret0_: UnsafeMutablePointer<Int32>?) throws {
        ret0_?.pointee = -1
    }
}

class PacketTunnelProvider: NEPacketTunnelProvider {
    private let callbacks = TunCallbacks()

    override func startTunnel(options: [String: NSObject]?, completionHandler: @escaping (Error?) -> Void) {
        let raw: [String: Any]
        let state: SharedState
        do {
            let data = try Data(contentsOf: NexoShared.sharedStateURL)
            raw = (try JSONSerialization.jsonObject(with: data) as? [String: Any]) ?? [:]
            state = try JSONDecoder().decode(SharedState.self, from: data)
        } catch {
            completionHandler(TunnelError.message("Open Nexo once to prepare the connection"))
            return
        }
        guard let vpn = state.vpnOptions, let setup = raw["setupParams"],
              let setupData = try? JSONSerialization.data(withJSONObject: setup)
        else {
            completionHandler(TunnelError.message("Choose a server in Nexo first"))
            return
        }
        let setupParams = String(decoding: setupData, as: UTF8.self)
        NexoMobileQuickSetup(NexoShared.initParams(), setupParams, CoreResultHandler { [weak self] result in
            let message = result.map { String(decoding: $0, as: UTF8.self) } ?? ""
            guard message.isEmpty else {
                completionHandler(TunnelError.message(message))
                return
            }
            self?.applySettings(vpn, completionHandler: completionHandler)
        })
    }

    private func applySettings(_ vpn: VpnOptions, completionHandler: @escaping (Error?) -> Void) {
        let settings = NEPacketTunnelNetworkSettings(tunnelRemoteAddress: "127.0.0.1")
        let mtu = (vpn.mtu ?? 0) > 0 ? min(max(vpn.mtu!, 1280), 65535) : defaultMtu
        settings.mtu = NSNumber(value: mtu)

        let ipv4 = NEIPv4Settings(addresses: [ipv4Address], subnetMasks: [ipv4Mask])
        ipv4.includedRoutes = routes(vpn.routeAddress, ipv6: false) ?? [NEIPv4Route.default()]
        settings.ipv4Settings = ipv4
        var servers = [dns4]
        if vpn.ipv6 {
            let ipv6 = NEIPv6Settings(addresses: [ipv6Address], networkPrefixLengths: [126])
            ipv6.includedRoutes = routes6(vpn.routeAddress) ?? [NEIPv6Route.default()]
            settings.ipv6Settings = ipv6
            servers.append(dns6)
        }
        let dnsSettings = NEDNSSettings(servers: servers)
        dnsSettings.matchDomains = [""]
        settings.dnsSettings = dnsSettings

        setTunnelNetworkSettings(settings) { [weak self] error in
            guard let self else { return }
            if let error {
                completionHandler(error)
                return
            }
            guard let fd = self.tunnelFileDescriptor else {
                completionHandler(TunnelError.message("No tunnel descriptor"))
                return
            }
            let tunOptions = ["mtu": mtu, "congestion-controller": vpn.congestionController ?? ""] as [String: Any]
            let optionsJson = String(decoding: try! JSONSerialization.data(withJSONObject: tunOptions), as: UTF8.self)
            let address = vpn.ipv6 ? "\(ipv4Address)/30,\(ipv6Address)/126" : "\(ipv4Address)/30"
            let dns = vpn.dnsHijacking ? "0.0.0.0" : servers.joined(separator: ",")
            // The Core closes the descriptor it is given; the original stays with the packet flow.
            let started = NexoMobileStartTun(dup(fd), self.callbacks, vpn.stack, address, dns, optionsJson)
            completionHandler(started ? nil : TunnelError.message("The tunnel did not start"))
        }
    }

    private func routes(_ cidrs: [String], ipv6: Bool) -> [NEIPv4Route]? {
        let parsed: [NEIPv4Route] = cidrs.compactMap { cidr in
            let parts = cidr.split(separator: "/")
            guard parts.count == 2, !parts[0].contains(":"), let bits = Int(parts[1]), (0...32).contains(bits) else {
                return nil
            }
            let mask = bits == 0 ? 0 : UInt32.max << (32 - UInt32(bits))
            let maskString = [24, 16, 8, 0].map { String((mask >> UInt32($0)) & 0xff) }.joined(separator: ".")
            return NEIPv4Route(destinationAddress: String(parts[0]), subnetMask: maskString)
        }
        return parsed.isEmpty ? nil : parsed
    }

    private func routes6(_ cidrs: [String]) -> [NEIPv6Route]? {
        let parsed: [NEIPv6Route] = cidrs.compactMap { cidr in
            let parts = cidr.split(separator: "/")
            guard parts.count == 2, parts[0].contains(":"), let bits = Int(parts[1]) else { return nil }
            return NEIPv6Route(destinationAddress: String(parts[0]), networkPrefixLength: NSNumber(value: bits))
        }
        return parsed.isEmpty ? nil : parsed
    }

    // NEPacketTunnelFlow keeps its utun socket private; find it among the open descriptors.
    private var tunnelFileDescriptor: Int32? {
        var buffer = [CChar](repeating: 0, count: Int(IFNAMSIZ))
        for fd: Int32 in 0...1024 {
            var length = socklen_t(buffer.count)
            if getsockopt(fd, 2, 2, &buffer, &length) == 0, String(cString: buffer).hasPrefix("utun") {
                return fd
            }
        }
        return packetFlow.value(forKeyPath: "socket.fileDescriptor") as? Int32
    }

    override func stopTunnel(with reason: NEProviderStopReason, completionHandler: @escaping () -> Void) {
        NexoMobileStopTun()
        NexoMobileStopListener()
        completionHandler()
    }

    override func handleAppMessage(_ messageData: Data, completionHandler: ((Data?) -> Void)?) {
        let payload = String(decoding: messageData, as: UTF8.self)
        NexoMobileInvokeMethod(payload, CoreResultHandler { result in
            completionHandler?(result)
        })
    }

    override func sleep(completionHandler: @escaping () -> Void) {
        NexoMobileForceGC()
        completionHandler()
    }
}

import Flutter
import NetworkExtension
import NexoCore

/// The iOS side of `lib/plugins/service.dart`: the app's own Core answers method calls, and the
/// Packet Tunnel extension runs a second Core started from the shared state the app writes.
final class ServicePlugin: NSObject, FlutterPlugin {
    private static let serviceChannelName = "com.follow.clash/service"
    private static let coreChannelName = "com.follow.clash/core"

    private let channel: FlutterMethodChannel
    private var commandRevision = 0
    private var runRequested = false
    private var manager: NETunnelProviderManager?
    private var statusObserver: NSObjectProtocol?

    init(channel: FlutterMethodChannel) {
        self.channel = channel
        super.init()
    }

    static func register(with registrar: FlutterPluginRegistrar) {
        let messenger = registrar.messenger()
        let channel = FlutterMethodChannel(name: serviceChannelName, binaryMessenger: messenger)
        let instance = ServicePlugin(channel: channel)
        registrar.addMethodCallDelegate(instance, channel: channel)
        let coreChannel = FlutterMethodChannel(
            name: coreChannelName,
            binaryMessenger: messenger,
            codec: FlutterStandardMethodCodec.sharedInstance(),
            taskQueue: messenger.makeBackgroundTaskQueue?()
        )
        coreChannel.setMethodCallHandler { call, result in
            guard call.method == "invokeMethod", let payload = call.arguments as? String else {
                result(FlutterMethodNotImplemented)
                return
            }
            instance.invokeCore(payload, result: result)
        }
        instance.observeStatus()
    }

    func handle(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
        switch call.method {
        case "init":
            NexoMobileSetEventListener(CoreResultHandler { [weak self] data in
                self?.sendEvent(data ?? Data())
            })
            result("")
        case "shutdown":
            NexoMobileSetEventListener(nil)
            result(true)
        case "syncState":
            result(syncState(call.arguments as? String))
        case "start":
            commandRevision = call.arguments as? Int ?? commandRevision
            runRequested = true
            startTunnel()
            result(true)
        case "stop":
            commandRevision = call.arguments as? Int ?? commandRevision
            runRequested = false
            manager?.connection.stopVPNTunnel()
            result(true)
        case "getRunTime":
            let date = manager?.connection.status == .connected ? manager?.connection.connectedDate : nil
            result(date.map { Int($0.timeIntervalSince1970 * 1000) } ?? 0)
        case "homeDir":
            result(NexoShared.homeURL.path)
        default:
            result(FlutterMethodNotImplemented)
        }
    }

    private func syncState(_ json: String?) -> String {
        guard let json, let data = json.data(using: .utf8) else {
            return "Invalid shared state"
        }
        do {
            try data.write(to: NexoShared.sharedStateURL, options: .atomic)
            return ""
        } catch {
            return error.localizedDescription
        }
    }

    private var tunnelSession: NETunnelProviderSession? {
        guard let session = manager?.connection as? NETunnelProviderSession,
              session.status == .connected
        else { return nil }
        return session
    }

    private func invokeCore(_ payload: String, result: @escaping FlutterResult) {
        let method = CoreRouting.methodName(of: payload) ?? ""
        let session = tunnelSession
        if let session, CoreRouting.tunnelOnly.contains(method) {
            sendToTunnel(session, payload) { data in
                result(data.map { FlutterStandardTypedData(bytes: $0) })
            }
            return
        }
        NexoMobileInvokeMethod(payload, CoreResultHandler { data in
            result(data.map { FlutterStandardTypedData(bytes: $0) })
        })
        if let session, CoreRouting.mirrored.contains(method) {
            sendToTunnel(session, payload) { _ in }
        }
    }

    private func sendToTunnel(_ session: NETunnelProviderSession, _ payload: String, reply: @escaping (Data?) -> Void) {
        do {
            try session.sendProviderMessage(Data(payload.utf8), responseHandler: reply)
        } catch {
            reply(nil)
        }
    }

    private func sendEvent(_ data: Data) {
        DispatchQueue.main.async {
            self.channel.invokeMethod("event", arguments: FlutterStandardTypedData(bytes: data))
        }
    }

    private func loadManager(_ done: @escaping (NETunnelProviderManager?) -> Void) {
        NETunnelProviderManager.loadAllFromPreferences { managers, _ in
            DispatchQueue.main.async {
                let existing = managers?.first
                self.manager = existing
                done(existing)
            }
        }
    }

    private func startTunnel() {
        loadManager { existing in
            let manager = existing ?? NETunnelProviderManager()
            let proto = NETunnelProviderProtocol()
            proto.providerBundleIdentifier = (Bundle.main.bundleIdentifier ?? "") + NexoShared.tunnelBundleSuffix
            proto.serverAddress = "Nexo"
            manager.protocolConfiguration = proto
            manager.localizedDescription = "Nexo"
            manager.isEnabled = true
            manager.saveToPreferences { error in
                if error != nil {
                    self.reportStopped()
                    return
                }
                // A saved configuration is only usable once it has been loaded back.
                manager.loadFromPreferences { _ in
                    DispatchQueue.main.async {
                        self.manager = manager
                        guard self.runRequested else { return }
                        do {
                            try manager.connection.startVPNTunnel()
                        } catch {
                            self.reportStopped()
                        }
                    }
                }
            }
        }
    }

    private func observeStatus() {
        loadManager { _ in }
        statusObserver = NotificationCenter.default.addObserver(
            forName: .NEVPNStatusDidChange, object: nil, queue: .main
        ) { [weak self] notification in
            guard let self, let connection = notification.object as? NEVPNConnection else { return }
            if connection.status == .disconnected, self.runRequested {
                self.reportStopped()
            }
        }
    }

    private func reportStopped() {
        DispatchQueue.main.async {
            self.runRequested = false
            self.channel.invokeMethod("stopped", arguments: self.commandRevision)
        }
    }
}

